		if (long?.status !== "on" || short?.status !== "on")
			throw new Error("PMI should be on");
		expect(short.pmi.endsMonth).toBeLessThan(long.pmi.endsMonth);
		expect(short.pmi.removalMonth).toBeLessThanOrEqual(short.pmi.endsMonth);
	});
});
