export const buildMonthlyEstimate = (
	loan: LoanDerivation | null,
	tax: PropertyTax | null,
	costs: MonthlyCosts | null,
	pmi: PmiResult | null,
): MonthlyEstimate | null => {
	if (!loan || !tax || !costs || !pmi) return null;

