export const buildArmSchedule = ({
	loan,
	startRate,
	payments,
	params,
	indexPath,
	extra,
}: ArmInput): ArmRow[] => {
	validateParams(params);
	if (!isMicros(startRate) || startRate < 0) {
		throw new RangeError("startRate must be a non-negative integer in millionths");
	}

	const rows: ArmRow[] = [];
	let balance = loan;
	let rate = startRate;
	let pi = monthlyPayment(loan, startRate, payments);
	let resets = 0;

