	expect(principal).toBe(loan);
	expect(extraTotal).toBe(rows.reduce((t, row) => t + row.extra, 0));
	let prev = start;
	let resets = 0;
	for (const row of rows) {
		expect(row.hypothetical).toBe(row.month > p.fixedMonths);
